// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait CustomerRequestAcquisition_Api {
  def id: Art.BridgeId
  def fresh_request_Id : Art.PortId
  def request_boundary_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var request_boundary_facts: Factory_Dispatch_Coordinator.RequestBoundaryFacts = $

  def put_request_boundary_facts(value : Factory_Dispatch_Coordinator.RequestBoundaryFacts) : Unit = {
    Contract(
      Modifies(request_boundary_facts),
      Ensures(
        request_boundary_facts == value
      )
    )
    Spec {
      request_boundary_facts = value
    }

    Art.putValue(request_boundary_facts_Id, Factory_Dispatch_Coordinator.RequestBoundaryFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class CustomerRequestAcquisition_Initialization_Api (
  val id: Art.BridgeId,
  val fresh_request_Id : Art.PortId,
  val request_boundary_facts_Id : Art.PortId) extends CustomerRequestAcquisition_Api

@datatype class CustomerRequestAcquisition_Operational_Api (
  val id: Art.BridgeId,
  val fresh_request_Id : Art.PortId,
  val request_boundary_facts_Id : Art.PortId) extends CustomerRequestAcquisition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var fresh_request: Factory_Dispatch_Coordinator.FreshRequest.Type = $

  def get_fresh_request() : Option[Factory_Dispatch_Coordinator.FreshRequest.Type] = {
    Contract(
      Ensures(
        Res == Some(fresh_request)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.FreshRequest.Type] = Art.getValue(fresh_request_Id) match {
      case Some(Factory_Dispatch_Coordinator.FreshRequest_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port fresh_request.  Expecting 'Factory_Dispatch_Coordinator.FreshRequest_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.FreshRequest.Type]()
      case _ => None[Factory_Dispatch_Coordinator.FreshRequest.Type]()
    }
    return value
  }
}
